// ---- putting a site up and taking it down
function st30Down(s){for(const o of s.objs||[]){o.hide=true;const i=OBJ.indexOf(o);if(i>=0)OBJ.splice(i,1);}
  for(const r of s.rects||[]){const i=rects.indexOf(r);if(i>=0)rects.splice(i,1);}
  for(const c of s.circles||[]){const i=circles.indexOf(c);if(i>=0)circles.splice(i,1);}
  for(const h of s.houses||[]){const i=HOUSES.indexOf(h);if(i>=0)HOUSES.splice(i,1);}
  for(const it of s.its||[]){const i=interact.indexOf(it);if(i>=0)interact.splice(i,1);}
  for(const [o,x,cs] of s.moved||[]){const d=x-o.x;o.x=x;for(const c of cs)c.x+=d;}
  if(s.room)st30RoomDown(s.room);s.objs=[];s.rects=[];s.circles=[];s.houses=[];s.its=[];s.moved=[];s.room=null;}
function st30Track(s,fn){const r0=rects.length,c0=circles.length,h0=HOUSES.length,o0=OBJ.length;const out=fn();
  s.rects.push(...rects.slice(r0));s.circles.push(...circles.slice(c0));s.houses.push(...HOUSES.slice(h0));s.objs.push(...OBJ.slice(o0));return out;}
